MENUS_SCRIPT = r"""
const notebookMenuIcon=name=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+({
  rename:'<path d="m4 16 11-12 5 5L9 21H4zM13 6l5 5"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7"/>',export:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',settings:'<path d="M3 6h18M3 12h18M3 18h18M8 3v6m8 0v6M9 15v6"/>',save:'<path d="M4 3h13l4 4v14H3V3zM7 3v7h10V3M7 21v-7h10v7"/>',image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1"/><path d="m3 17 5-5 4 4 4-6 5 7"/>',file:'<path d="M5 3h9l5 5v13H5zM14 3v6h5M8 13h8M8 17h5"/>',backup:'<path d="M4 7h16v14H4zM3 3h18v4H3M9 11h6"/>',import:'<path d="M12 16V3m-5 8 5 5 5-5M4 17v4h16v-4"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',check:'<path d="m4 12 5 5L20 6"/>'
}[name]||'')+'</svg>';
function notebookModal(id,title,body){const node=document.createElement('div');node.id=id;node.className='notebook-modal';node.hidden=true;node.innerHTML=`<section class="notebook-modal-card" role="dialog" aria-modal="true" aria-label="${title}"><div class="sheet-head"><h2>${title}</h2><button type="button" class="icon-button" aria-label="閉じる">${notebookMenuIcon('close')}</button></div>${body}</section>`;node.querySelector('.sheet-head button').addEventListener('click',()=>node.hidden=true);node.addEventListener('pointerdown',e=>{if(e.target===node)node.hidden=true;});document.body.appendChild(node);return node;}
notebookModal('notebook-export','書き出しとバックアップ',`<p>いま開いているノートを書き出します。</p><button type="button" class="file-choice" data-note-file="pdf">${notebookMenuIcon('file')}<span><strong>PDF</strong><small>ノートの全ページを1つのPDFに</small></span></button><button type="button" class="file-choice" data-note-file="png">${notebookMenuIcon('image')}<span><strong>画像（PNG）</strong><small>今のページを1枚の画像に</small></span></button><div class="section-label">あとから編集できるバックアップ</div><button type="button" class="file-choice" data-note-file="backup">${notebookMenuIcon('backup')}<span><strong>このノートをバックアップ</strong><small>.spennotes ファイルで保存</small></span></button><button type="button" class="file-choice" data-note-file="backup_all">${notebookMenuIcon('backup')}<span><strong>すべてのノートをバックアップ</strong><small>ゴミ箱を含む、ノート全体の控え</small></span></button><button type="button" class="save-secondary" id="export-import">バックアップを取り込む</button><div id="notebook-file-message" class="file-message" role="status"></div>`);
notebookModal('notebook-attachments','添付資料','<p>このノートに関連する資料を保存できます（1ファイル10 MiBまで）。</p><div id="notebook-attachment-list"></div><button type="button" id="notebook-attach" class="save-primary">資料を追加</button>');
notebookModal('notebook-save','保存状態',`<div class="save-detail">${notebookMenuIcon('check')}<div><strong id="save-detail-title"></strong><small id="save-detail-date"></small></div></div><p id="save-detail-description">ノートは接続先のPCに自動保存されます。</p><button type="button" id="save-now" class="save-primary">今すぐ保存</button><button type="button" id="save-backup" class="save-secondary">書き出し・バックアップ</button>`);
notebookModal('input-settings','入力の設定','<label for="pen-button-mode">S Penボタン</label><div id="input-button-setting"></div><p>ペンを近づけてボタンをダブルクリックすると、ペンに戻ってお気に入りを開きます。</p><label class="input-toggle" id="input-pen-only"></label>');
const notebookOriginalCloseOverlays=closeOverlays;
closeOverlays=function(){notebookOriginalCloseOverlays();for(const id of ['notebook-export','notebook-save','input-settings','notebook-attachments'])$(id).hidden=true;};
function openNotebookModal(id){finishActiveInput();closeOverlays();$(id).hidden=false;}
const notebookPaperSelect=$('paper-style'),notebookButtonSelect=$('pen-button-mode'),notebookPenOnly=$('penOnlyToggle');
notebookPaperSelect.setAttribute('aria-label','用紙');
$('input-button-setting').appendChild(notebookButtonSelect);$('input-pen-only').append(notebookPenOnly,document.createTextNode('ペンのみで書く（指は移動・拡大）'));
const notebookPaste=$('paste-ink');
$('note-options').innerHTML=`<div class="sheet-head"><h2>ノート</h2><button type="button" id="close-options" class="icon-button" aria-label="閉じる">${notebookMenuIcon('close')}</button></div><div class="menu-section" id="note-actions"><div class="menu-section-title">ノートの操作</div></div><div class="menu-section"><div class="menu-paper-row"><span>用紙</span><div id="menu-paper"></div></div></div><div class="menu-section" id="note-files"></div><div class="menu-section" id="note-input"></div><div class="menu-section" id="note-edit"></div>`;
$('close-options').addEventListener('click',()=>closeOverlays());$('menu-paper').appendChild(notebookPaperSelect);
function notebookMenuRow(parent,id,label,icon,handler,danger=false){const b=document.createElement('button');b.type='button';b.id=id;b.className='note-menu-row'+(danger?' danger':'');b.innerHTML=notebookMenuIcon(icon)+'<span></span>';b.querySelector('span').textContent=label;b.addEventListener('click',handler);$(parent).appendChild(b);return b;}
notebookMenuRow('note-actions','menu-rename','名前を変更','rename',()=>{closeOverlays();openNotebookRename(notebookLibraryCurrentId());});
notebookMenuRow('note-actions','menu-course','科目を変更','backup',()=>{closeOverlays();openNotebookRename(notebookLibraryCurrentId(),'course');});
notebookMenuRow('note-actions','menu-duplicate','複製','copy',()=>{closeOverlays();requestNotebookLibraryAction('duplicate',notebookLibraryCurrentId());});
notebookMenuRow('note-actions','menu-trash','ゴミ箱へ移動','trash',()=>{closeOverlays();requestNotebookLibraryAction('trash',notebookLibraryCurrentId());},true);
notebookMenuRow('note-files','export-note','書き出し・バックアップ','export',()=>openNotebookExport());
notebookMenuRow('note-files','menu-attachments','添付資料','file',()=>{renderNotebookAttachments();openNotebookModal('notebook-attachments');});
notebookMenuRow('note-files','menu-save','保存状態','save',()=>openNotebookSave());
notebookMenuRow('note-input','menu-input','入力の設定','settings',()=>openNotebookModal('input-settings'));
if(notebookPaste){notebookPaste.className='note-menu-row';$('note-edit').appendChild(notebookPaste);}
notebookMenuRow('note-edit','clear-note','このページの筆跡を消す','trash',()=>{finishActiveInput();const sent=sendWS({type:'clear'});closeOverlays();if(sent)showToast('筆跡を消しました。「元に戻す」で復元できます');},true);
const notebookSaveButton=document.createElement('button');notebookSaveButton.type='button';notebookSaveButton.id='save-status';notebookSaveButton.setAttribute('aria-label','保存状態を確認');$('save-status').replaceWith(notebookSaveButton);notebookSaveButton.addEventListener('click',()=>openNotebookSave());
let notebookSaveState='connecting',notebookSavedAt=null,notebookSaveError='',notebookDeferredSave=null,notebookFileSequence=0,notebookSaveCheckpoint=null,notebookSaveSequence=0;
const notebookSaveSession=Math.random().toString(36).slice(2);
const notebookFileRequests=new Map();
function notebookSaveLabel(){return {connecting:'接続中',offline:'未接続',dirty:'保存待ち',saving:'保存中…',saved:'保存済み',error:'保存失敗'}[notebookSaveState]||'保存を確認';}
function renderNotebookSave(){notebookSaveButton.dataset.state=notebookSaveState;notebookSaveButton.textContent=notebookSaveLabel();notebookSaveButton.title=notebookSaveState==='saved'?'PCに保存済み':'クリックして保存状態を確認';$('save-detail-title').textContent=notebookSaveState==='saved'?'PCに保存済み':notebookSaveLabel();$('save-detail-date').textContent=notebookSavedAt?'最終保存 '+new Date(notebookSavedAt).toLocaleString('ja-JP'):'保存日時を確認中';$('save-detail-description').textContent=notebookSaveState==='error'?(notebookSaveError||'PCに保存できませんでした。バックアップを書き出して保護できます。'):notebookSaveState==='offline'?'PCに再接続すると、保存状態を確認できます。':'ノートは接続先のPCに自動保存されます。別の場所に控えを残すにはバックアップを使えます。';$('save-now').disabled=!notebookReady;$('save-now').textContent=notebookSaveState==='error'?'もう一度保存':'今すぐ保存';}
function notebookInputPending(){return isDrawing||(typeof inkPointerId!=='undefined'&&inkPointerId!==null)||(typeof selectionRequest!=='undefined'&&!!selectionRequest);}
function applyNotebookSave(message){if(message.noteId&&message.noteId!==currentDocumentId)return;const state=message.state||'saved';if(state==='saved'&&(notebookInputPending()||notebookSaveCheckpoint&&!message.saveCheckpoints?.includes(notebookSaveCheckpoint))){notebookDeferredSave=message;return;}if(state==='saved'){notebookSaveCheckpoint=null;notebookDeferredSave=null;}notebookSaveState=state;if(message.savedAt)notebookSavedAt=message.savedAt;notebookSaveError=message.message||'';renderNotebookSave();}
function flushNotebookSaveAck(){if(notebookDeferredSave&&!notebookInputPending()){const message=notebookDeferredSave;notebookDeferredSave=null;applyNotebookSave(message);}}
function requestNotebookSaveCheckpoint(){const requestId='save_'+notebookSaveSession+'_'+(++notebookSaveSequence);notebookSaveCheckpoint=requestId;notebookDeferredSave=null;if(!sendWS({type:'note_save_checkpoint',documentId:currentDocumentId,requestId}))notebookSaveCheckpoint=null;}
function flushNotebookTitle(){clearTimeout(titleTimer);const id=notebookLibraryCurrentId();if(!id)return;const title=$('note-title').value.trim()||'新しいノート',note=notes.find(n=>n.id===id);if(note&&note.title===title)return;sendWS({type:'note_title',id,title});}
function saveNotebookNow(){finishActiveInput();flushNotebookTitle();if(sendWS({type:'note_save'})){notebookSaveState='saving';renderNotebookSave();}}
function openNotebookSave(){openNotebookModal('notebook-save');renderNotebookSave();}
function notebookFileMessage(message,error=false){$('notebook-file-message').textContent=message;$('notebook-file-message').classList.toggle('error',error);}
function openNotebookExport(){flushNotebookTitle();openNotebookModal('notebook-export');notebookFileMessage('');}
function requestNotebookFile(action,data){finishActiveInput();flushNotebookTitle();const requestId='file_'+Date.now().toString(36)+'_'+(++notebookFileSequence);if(!sendWS({type:'note_file',action,requestId,documentId:currentDocumentId,...data}))return;notebookFileRequests.set(requestId,{action});notebookFileMessage(action==='import'?'バックアップを取り込んでいます…':'ファイルを作成しています…');for(const button of document.querySelectorAll('[data-note-file]'))button.disabled=true;}
const notebookImportInput=document.createElement('input');notebookImportInput.type='file';notebookImportInput.accept='.spennotes,.json,application/json';notebookImportInput.hidden=true;document.body.appendChild(notebookImportInput);
function importNotebookBackup(){notebookImportInput.value='';notebookImportInput.click();}
notebookImportInput.addEventListener('change',async()=>{const file=notebookImportInput.files[0];if(!file)return;openNotebookExport();if(file.size>10*1024*1024){notebookFileMessage('10MB以内のバックアップを選んでください。',true);return;}try{const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));requestNotebookFile('import',{data:btoa(binary)});}catch(_){notebookFileMessage('ファイルを読み込めませんでした。',true);}});
function renderNotebookAttachments(){
  const list=$('notebook-attachment-list');list.replaceChildren();
  const items=notes.find(n=>n.id===notebookLibraryCurrentId())?.attachments||[];
  if(!items.length){const empty=document.createElement('p');empty.textContent='添付資料はありません';list.appendChild(empty);}
  for(const item of items){const row=document.createElement('div'),download=document.createElement('button'),remove=document.createElement('button');download.type=remove.type='button';download.className='file-choice';download.textContent=item.name+'（'+Math.ceil(item.bytes/1024)+' KB）';download.addEventListener('click',()=>requestNotebookFile('attachment_download',{attachmentId:item.id}));remove.className='save-secondary';remove.textContent='このノートから外す';remove.setAttribute('aria-label',item.name+' を外す');remove.addEventListener('click',()=>requestNotebookFile('attachment_remove',{attachmentId:item.id}));row.append(download,remove);list.appendChild(row);}
}
const notebookAttachmentInput=document.createElement('input');notebookAttachmentInput.type='file';notebookAttachmentInput.hidden=true;document.body.appendChild(notebookAttachmentInput);
$('notebook-attach').addEventListener('click',()=>{notebookAttachmentInput.value='';notebookAttachmentInput.click();});
notebookAttachmentInput.addEventListener('change',async()=>{const file=notebookAttachmentInput.files[0];if(!file)return;if(!file.size||file.size>10*1024*1024){showToast('空でない10 MiB以内の資料を選んでください');return;}const noteId=currentDocumentId;try{const bytes=new Uint8Array(await file.arrayBuffer());if(noteId!==currentDocumentId){showToast('ノートが切り替わりました。選び直してください');return;}let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));requestNotebookFile('attach',{filename:file.name,data:btoa(binary)});}catch(_){showToast('資料を読み込めませんでした');}});
function downloadNotebookFile(message){const binary=atob(message.data),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);const url=URL.createObjectURL(new Blob([bytes],{type:message.mime})),a=document.createElement('a');a.href=url;a.download=message.filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
for(const button of document.querySelectorAll('[data-note-file]'))button.addEventListener('click',()=>requestNotebookFile(button.dataset.noteFile));
$('export-import').addEventListener('click',importNotebookBackup);$('save-now').addEventListener('click',saveNotebookNow);$('save-backup').addEventListener('click',openNotebookExport);
for(const [label,handler] of [['バックアップ',openNotebookExport],['取り込む',importNotebookBackup]]){const b=document.createElement('button');b.type='button';b.textContent=label;b.addEventListener('click',handler);$('library-file-actions').appendChild(b);}
const notebookMenusSendWS=sendWS;
sendWS=function(message){const sent=notebookMenusSendWS(message);if(sent&&['stroke_start','stroke_move','line_update','erase','clear','undo','redo','note_title','note_paper','note_ink_edit'].includes(message.type)){notebookDeferredSave=null;notebookSaveState='dirty';renderNotebookSave();}if(sent&&(['clear','undo','redo','note_title','note_paper'].includes(message.type)||['stroke_end','erase_end'].includes(message.type)&&notebookSaveState!=='saved'))requestNotebookSaveCheckpoint();return sent;};
const notebookMenusHandleMessage=handleServerMessage;
handleServerMessage=function(message){
  if(message.type==='note_file_result'){const pending=notebookFileRequests.get(message.requestId);if(!pending)return;notebookFileRequests.delete(message.requestId);for(const button of document.querySelectorAll('[data-note-file]'))button.disabled=notebookFileRequests.size>0;if(!message.ok){notebookFileMessage(message.message||'操作に失敗しました。',true);showToast(message.message||'ファイル操作に失敗しました');return;}if(pending.action==='import'){notebookFileMessage(`${message.importedCount} 件のノートを取り込みました。元のノートも残っています。`);showToast('バックアップを取り込みました');}else if(['attach','attachment_remove'].includes(pending.action)){renderNotebookAttachments();showToast(pending.action==='attach'?'資料を追加しました':'添付資料を外しました');}else{downloadNotebookFile(message);notebookFileMessage(message.saved===false?'ファイルを書き出しました。PCへの保存は再試行してください。':'ファイルを書き出しました');}return;}
  const syncWasPending=message.type==='state_sync'&&message.documentId===currentDocumentId&&notebookInputPending(),previousDocument=currentDocumentId,pendingSelection=typeof selectionRequest!=='undefined'?selectionRequest:null;
  notebookMenusHandleMessage(message);
  if(message.type==='state_sync'){renderNotebookAttachments();const saved={noteId:message.documentId,state:message.saveState||'saved',savedAt:message.savedAt,message:message.saveError,saveCheckpoints:message.saveCheckpoints};if(previousDocument!==currentDocumentId){notebookDeferredSave=null;notebookSaveCheckpoint=null;notebookSavedAt=message.savedAt||null;}if(syncWasPending&&saved.state==='saved'){notebookDeferredSave=saved;renderNotebookSave();}else applyNotebookSave(saved);}
  else if(message.type==='note_save_state'||message.type==='note_saved')applyNotebookSave(message);
  else if(message.type==='note_ink_edit_result'&&pendingSelection&&message.requestId===pendingSelection)requestNotebookSaveCheckpoint();
  else if(message.type==='note_error')renderNotebookSave();
};
const notebookMenusConnection=updateExtensionConnection;
updateExtensionConnection=function(connected){notebookMenusConnection(connected);notebookSaveState=connected?'connecting':'offline';notebookDeferredSave=null;notebookSaveCheckpoint=null;renderNotebookSave();if(!connected){for(const button of document.querySelectorAll('[data-note-file]'))button.disabled=false;if(notebookFileRequests.size)notebookFileMessage('接続が切れました。再接続してから、もう一度お試しください。',true);notebookFileRequests.clear();}};
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();saveNotebookNow();}});
renderNotebookSave();
"""
